    lessons=[L19, L20, L21],
    bilan=['Je connais les trois règles du mîm sâkin.', 'Je fais l’ikhfâ’ chafawî et l’idghâm du mîm avec deux temps de ghounna.', 'Je prononce clairement le mîm devant و et ف.', 'Je tiens deux temps de ghounna sur نّ et مّ.'],
